import { ConvexError } from "convex/values";
import type { QueryCtx, MutationCtx, ActionCtx } from "./_generated/server";

export async function principal(ctx: Pick<QueryCtx | MutationCtx | ActionCtx, "auth">): Promise<string> {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) throw new ConvexError({ version: 1, code: "UNAUTHENTICATED", retryable: false });
  if (!["task01-owner", "task01-other-owner"].includes(identity.subject)) throw new ConvexError({ version: 1, code: "FORBIDDEN", retryable: false });
  return identity.subject;
}

import { defineApp } from "convex/server";
import agent from "@convex-dev/agent/convex.config";
import workflow from "@convex-dev/workflow/convex.config";
import workpool from "@convex-dev/workpool/convex.config";

const app = defineApp();
app.use(agent);
app.use(workflow);
app.use(workpool);
export default app;

import { v } from "convex/values";
import { internal } from "./_generated/api";
import { workflow } from "./runtime";

export const execute = workflow.define({
  args: { runId: v.id("runs") },
  returns: v.null(),
  handler: async (step,args): Promise<null> => {
    await step.runAction(internal.inference.execute, args, { retry: false });
    return null;
  },
});

import { httpRouter } from "convex/server";
import { internal } from "./_generated/api";
import { httpAction } from "./_generated/server";

const http=httpRouter();
http.route({path:"/fixture-effect",method:"POST",handler:httpAction(async(ctx,request)=>{
  const expected=process.env.QUALIFICATION_EFFECT_SECRET;
  if(!expected||request.headers.get("x-fixture-secret")!==expected) return new Response("Forbidden",{status:403});
  const body:unknown=await request.json();
  if(!body||typeof body!=="object"||!("operationId" in body)||typeof body.operationId!=="string") return new Response("Bad request",{status:400});
  return Response.json(await ctx.runMutation(internal.interrupted.effect,{operationId:body.operationId}));
})});
export default http;

import { Agent, createTool, mockModel, type ToolCtx } from "@convex-dev/agent";
import { convexGateway } from "@convex-dev/ai-sdk-provider";
import { Output, generateText, stepCountIs } from "ai";
import { ConvexError, v } from "convex/values";
import { z } from "zod";
